776	/*-----------------------------------------
777	 * 'plain' prime search: can modn[] indicate a prime?
778	 *
779	 * SECURITY NOTE: tmp[] and tmp2[] are scratch, filled with (potentially)secret
780	 * state-dependent data, and SHOULD be wiped upon return.
781	 */
782	static inline
783	REALLY_FORCE_INLINE
784	/**/
785	uint16_t simd_nofactor64x16(uint16_t tmp[static 64],
786	                           uint16_t tmp2[static 64],
787	                     const uint16_t modn[static 64],
788	                      const uint16_t inv[static 64],
789	                    const uint16_t limit[static 64])
790	{
791						// compute n * 1/prime  mod 2^16
792	
793		simd_mul16x16(  tmp,          modn,          inv       );
794		simd_mul16x16(&(tmp[ 16 ]), &(modn[ 16 ]), &(inv[ 16 ]));
795		simd_mul16x16(&(tmp[ 32 ]), &(modn[ 32 ]), &(inv[ 32 ]));
796		simd_mul16x16(&(tmp[ 48 ]), &(modn[ 48 ]), &(inv[ 48 ]));
797	
798						// any of the products <= limit[ ]?
799						// divides -> ffff; not -> 0
800	
801		simd_lemask16x16_inpl(  tmp,          limit       );
802		simd_lemask16x16_inpl(&(tmp[ 16 ]), &(limit[ 16 ]));
803		simd_lemask16x16_inpl(&(tmp[ 32 ]), &(limit[ 32 ]));
804		simd_lemask16x16_inpl(&(tmp[ 48 ]), &(limit[ 48 ]));
805	
806		return simd_is_all0x64x16_inpl(tmp, tmp2);
807	}
