492	/*--------------------------------------
493	 * reduce v[] in-place mod-small-primes[] (if entries are >= 0x8000)
494	 *
495	 * assume aggressive+forced inlining leads to recognized specialization
496	 * for src==dest; we do not replicate the simd_m2range16x16() fn. body
497	 * here
498	 */
499	static inline
500	REALLY_FORCE_INLINE
501	//
502	void simd_m2range16x16_inpl(uint16_t v[static 16],
503	                    const uint16_t m2r[static 16])
504	{
505		simd_m2range16x16(v, v, m2r);
506	}
