667	// note: zero-flag (ZF) checking for 256-bit wide SIMD units
668	// above, we rely on the all-0 16x16-bit representation 
669	//
670	// there are equivalent intrinsics, or even the straightforward AND-all
671	// of 16x16 bits may turn into a short construct. TBD
672	//
673	#if 0
674	#if (SYS__X86_BITS >= 64)
675		return _mm256_testz_si256((const __m256i) *v, (const __m256i) *v);
676			// 
677			// compare-all-0 compiles into vpxor, vptest "close enough"
678	
679	#elif (SYS__AARCH >= 64)
680		return (vmaxvq_u16(v) == 0);
681			// MAX(..16x16 bits..); does not require use of all-0
682			// aux. register
683			//
684			// compiles into:
685			//     umaxv hd,vn.8h   "Unsigned Maximum across Vector"
686			//
687			// see developer.arm.com/architectures/instruction-sets/
688			//     intrinsics/vmaxvq_u16
689	
690	#elif (SYS__S390_BITS >= 64)
691	#error "supply S390 check-ZF(compare-0) intrinsic here"
692	
693	#else
694		return !!((((v[  0 ] | v[  1 ]) | (v[  2 ] | v[  3 ]))  &
695		           ((v[  4 ] | v[  5 ]) | (v[  6 ] | v[  7 ]))) &
696		          (((v[  8 ] | v[  9 ]) | (v[ 10 ] | v[ 11 ]))  &
697		           ((v[ 12 ] | v[ 13 ]) | (v[ 14 ] | v[ 15 ]))));
698			// note the 8x2 split
699			// expect to be specialized into faster-than-16x expression
700	
701	#endif
702	#endif
703	#endif       // /256 bits
