2022	                               uint16_t tm2[static 64],
2023	                        const uint16_t modn[static 64], 
2024	                         const uint16_t inv[static 64],
2025	                       const uint16_t limit[static 64])
2026	{
2027					// compute n * 1/prime  mod 2^16 products
2028	
2029		simd_mul16x16(  tmp,          modn,          inv       );
2030		simd_mul16x16(&(tmp[ 16 ]), &(modn[ 16 ]), &(inv[ 16 ]));
2031		simd_mul16x16(&(tmp[ 32 ]), &(modn[ 32 ]), &(inv[ 32 ]));
2032		simd_mul16x16(&(tmp[ 48 ]), &(modn[ 48 ]), &(inv[ 48 ]));
2033	
2034		simd_spcmp16x16(  tmp,         tmp,         inv,         limit       );
2035		simd_spcmp16x16(&(tmp[ 16 ]),&(tmp[ 16 ]),&(inv[ 16 ]),&(limit[ 16 ]));
2036		simd_spcmp16x16(&(tmp[ 32 ]),&(tmp[ 32 ]),&(inv[ 32 ]),&(limit[ 32 ]));
2037		simd_spcmp16x16(&(tmp[ 48 ]),&(tmp[ 48 ]),&(inv[ 48 ]),&(limit[ 48 ]));
2038	
2039		return simd_is_all0x64x16_inpl(tmp, tm2);
2040	}
