2044	#if !defined(NO_SIMD_TWINPRIME)  //---- twin prime: u and (u + 2) primes -----
2045	/*--------------------------------------
2046	 * report if P|n or P|n+2 for P from prime[]
2047	 *
2048	 * rely on n*(1/P) <= limit(P) <=> P divides n
2049	 * we check (n*(1/P) <= limit(P)) and ((2*n+1)*(1/P) <= limit(P)) by
2050	 * checking min(n*(1/p), (2*n+1)*(1/P)) <= limit(P), saving a multiplication
2051	 *
2052	 * 'u' contains n * 1/prime[]
2053	 * 'r' is filled with 16x16-bit result
2054	 *     ffff  entry in prime[] divides n  OR  divides 2n+1
2055	 *        0  prime[] is not a factor
2056	 * 'r' and 'u' may point to the same memory; MUST NOT overlap with 'tmp'
2057	 *
2058	 * 'tmp' is centralized scratch, filled with (potentially)secret-dependent data
2059	 *
2060	 * TODO: check whether storing 2/p[] is more efficient than 2*(1/p)
2061	 * unlikely: shift-by-1 only generates only one instruction; we are
2062	 * probably better off than using another set of []-sized constants
2063	 *--------------------------------------*/
2064	static inline
2065	REALLY_FORCE_INLINE
2066	//
2067	void simd_cmp16x16_twin(uint16_t   r[static  16],
2068	                        uint16_t tmp[static  16],
2069	                  const uint16_t   u[static  16],
2070	                  const uint16_t inv[static  16],
2071	                const uint16_t limit[static  16])
2072	{
2073		simd_shladd16x16(tmp, inv, u);          // (u * 1/p) + 2/p =~ u/p + 2/p
2074	
2075		simd_min16x16(r, tmp, u);               // min(u/p + 2/p, u/p)
2076	
2077		simd_lemask16x16_inpl(r, limit);
2078	}
