2081	/*--------------------------------------
2082	 * does this modn[] (->N) slice indicate a small-prime factor of N or 2N+1?
2083	 *
2084	 * tmp[] and tm2[] are different scratch registers
2085	 */
2086	static inline
2087	REALLY_FORCE_INLINE
2088	/**/
2089	uint16_t simd_no_twinfactor64x16(uint16_t tmp[static 64],
2090	                                 uint16_t tm2[static 64],
2091	                          const uint16_t modn[static 64],
2092	                           const uint16_t inv[static 64],
2093	                         const uint16_t limit[static 64])
2094	{
2095						// tmp[] = modn[] * 1/prime[]  mod 2^16
2096	
2097		simd_mul16x16(  tmp,          modn,          inv       );
2098		simd_mul16x16(&(tmp[ 16 ]), &(modn[ 16 ]), &(inv[ 16 ]));
2099		simd_mul16x16(&(tmp[ 32 ]), &(modn[ 32 ]), &(inv[ 32 ]));
2100		simd_mul16x16(&(tmp[ 48 ]), &(modn[ 48 ]), &(inv[ 48 ]));
2101	
2102		simd_cmp16x16_twin(  tmp,          tm2,         tmp,         inv,
2103		                   limit);
2104		simd_cmp16x16_twin(&(tmp[ 16 ]), &(tm2[ 16 ]),&(tmp[ 16 ]),&(inv[ 16 ]),
2105	                         &(limit[ 16 ]));
2106		simd_cmp16x16_twin(&(tmp[ 32 ]), &(tm2[ 32 ]),&(tmp[ 32 ]),&(inv[ 32 ]),
2107	                         &(limit[ 32 ]));
2108		simd_cmp16x16_twin(&(tmp[ 48 ]), &(tm2[ 48 ]),&(tmp[ 48 ]),&(inv[ 48 ]),
2109	                         &(limit[ 48 ]));
2110	
2111		return simd_is_all0x64x16_inpl(tmp, tm2);
2112	}
